<!doctype html>
<html lang="en">
<head>
    <meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
    <meta name="csrf-token" content="{{ csrf_token() }}">
    <title>Tasks · Daymark</title>
    <link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700&display=swap" rel="stylesheet">
    <style>
        :root{--ink:#18231f;--muted:#77817b;--line:#e7ebe7;--paper:#fbfcfa;--green:#38745b;--pale:#edf5ef;--red:#ae5f56}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:14px 'DM Sans',sans-serif}button,input,textarea{font:inherit}button{cursor:pointer}.app{min-height:100vh;display:grid;grid-template-columns:225px 1fr}.sidebar{background:#f5f7f3;border-right:1px solid var(--line);padding:24px 15px;display:flex;flex-direction:column}.brand{display:flex;align-items:center;gap:10px;font-weight:700;padding:0 8px 36px}.mark{width:30px;height:30px;background:var(--green);border-radius:9px;display:grid;place-items:center;color:white}.label{font:500 10px 'DM Mono';text-transform:uppercase;letter-spacing:1px;color:#98a19a;padding:0 10px 10px}.nav{display:grid;gap:4px}.nav-item{padding:10px;border-radius:7px;color:#69736c;font-size:13px}.nav-item.active{background:#e7efe8;color:#315d49;font-weight:600}.server{margin-top:auto;border:1px solid #e3e9e3;border-radius:9px;padding:13px;font-size:12px}.status{color:#78847b;font:10px 'DM Mono';margin-top:8px}.dot{display:inline-block;width:7px;height:7px;border-radius:50%;background:#58a479;margin-right:7px}.main{max-width:1080px;width:100%;margin:auto;padding:35px 48px}.top{display:flex;justify-content:space-between;color:#929c94;font-size:12px;margin-bottom:44px}.avatar{width:31px;height:31px;border:1px solid var(--line);border-radius:50%;display:grid;place-items:center;color:#637067;background:white}.intro{display:flex;align-items:flex-end;justify-content:space-between;margin-bottom:27px}.eyebrow{font:11px 'DM Mono';text-transform:uppercase;letter-spacing:1px;color:var(--green);margin-bottom:9px}.intro h1{font-size:31px;letter-spacing:-1px;margin:0 0 7px;font-weight:600}.intro p{margin:0;color:var(--muted);font-size:13px}.primary{border:0;border-radius:7px;padding:10px 15px;background:var(--green);color:white;font-size:12px;font-weight:600}.summary{display:flex;gap:24px;border-bottom:1px solid var(--line);padding:0 0 19px;margin-bottom:18px}.metric{font-size:11px;color:#89938c}.metric strong{font:500 14px 'DM Mono';color:#435149;margin-right:5px}.toolbar{display:flex;align-items:center;justify-content:space-between;margin-bottom:12px}.tabs{display:flex;gap:4px}.tab{border:0;background:none;color:#879189;padding:8px 11px;border-radius:6px;font-size:12px}.tab.active{background:#eaf2eb;color:#315d49;font-weight:600}.search{height:34px;width:210px;border:1px solid var(--line);border-radius:6px;background:white;padding:0 10px}.search input{border:0;outline:0;width:100%;height:100%;font-size:11px}.task-list{display:grid;gap:8px}.task{background:white;border:1px solid var(--line);border-radius:8px;padding:15px 16px;display:grid;grid-template-columns:20px 1fr auto;align-items:start;gap:12px}.task:hover{border-color:#c7d5c9}.check{appearance:none;width:17px;height:17px;border:1.5px solid #c6cec7;border-radius:50%;margin:2px 0 0;cursor:pointer;position:relative}.check:checked{background:var(--green);border-color:var(--green)}.check:checked:after{content:'✓';position:absolute;color:white;font-size:11px;left:3px;top:0}.task-title{font-size:13px;font-weight:600}.task.done .task-title{text-decoration:line-through;color:#98a19a}.task-desc{font-size:11px;color:#818a83;margin-top:5px;line-height:1.45;white-space:pre-wrap}.due{font:10px 'DM Mono';color:#858f87;margin-top:8px}.actions{display:flex;gap:5px}.icon-btn{border:0;background:transparent;color:#88938b;padding:5px;border-radius:5px;font-size:11px}.icon-btn:hover{background:#f0f3ef;color:#435149}.icon-btn.delete:hover{background:#fbefed;color:var(--red)}.empty{border:1px dashed #dfe5df;border-radius:9px;padding:48px 18px;text-align:center;background:white;color:#849087}.empty strong{display:block;color:#4c5b51;margin-bottom:6px;font-size:14px}.toast{position:fixed;bottom:22px;left:50%;transform:translateX(-50%);padding:11px 16px;border-radius:7px;color:white;background:#263b30;box-shadow:0 6px 24px #142b1d30;font-size:12px;opacity:0;pointer-events:none;transition:opacity .2s}.toast.show{opacity:1}.modal-backdrop{position:fixed;inset:0;background:#18231f66;display:none;align-items:center;justify-content:center;padding:20px;z-index:2}.modal-backdrop.open{display:flex}.modal{width:min(460px,100%);background:white;border-radius:12px;padding:23px;box-shadow:0 20px 60px #10221830}.modal-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:19px}.modal h2{font-size:18px;letter-spacing:-.4px;margin:0}.close{border:0;background:none;color:#849087;font-size:20px}.field{display:grid;gap:6px;margin-bottom:14px}.field label{font-size:11px;font-weight:600;color:#58645b}.field input,.field textarea{width:100%;border:1px solid #e0e6e0;border-radius:6px;padding:10px;font-size:12px;outline:none}.field input:focus,.field textarea:focus{border-color:#80a58a;box-shadow:0 0 0 3px #38745b18}.field textarea{min-height:82px;resize:vertical}.form-error{color:#a8423a;font-size:11px;margin:0 0 12px;display:none}.modal-actions{display:flex;justify-content:flex-end;gap:8px;margin-top:19px}.secondary{border:1px solid var(--line);background:white;border-radius:6px;padding:9px 13px;font-size:12px;color:#59645c}.save{border:0;background:var(--green);color:white;border-radius:6px;padding:9px 14px;font-size:12px;font-weight:600}.save:disabled{opacity:.6;cursor:wait}@media(max-width:720px){.app{display:block}.sidebar{display:none}.main{padding:22px 16px}.top{margin-bottom:32px}.intro{align-items:flex-start;gap:16px;flex-direction:column}.intro h1{font-size:27px}.toolbar{align-items:flex-start;gap:10px;flex-direction:column}.search{width:100%}.task{grid-template-columns:20px 1fr auto;padding:13px 11px}.actions{flex-direction:column}.summary{gap:14px}.metric{font-size:10px}}
    </style>
</head>
<body>
<div class="app"><aside class="sidebar"><div class="brand"><span class="mark"><svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="m5 12 4 4L19 6"/></svg></span> daymark</div><div class="label">Workspace</div><nav class="nav"><div class="nav-item active">✓ &nbsp; Tasks</div><div class="nav-item">◈ &nbsp; Tools</div></nav><div class="server"><span class="dot"></span>Todo MCP server<div class="status">Connected · v0.0.1</div></div></aside>
<main class="main"><header class="top"><span>Workspace / <strong style="color:#536159;font-weight:500">Tasks</strong></span><span class="avatar">CY</span></header><section class="intro"><div><div class="eyebrow">Your day, in focus</div><h1>Tasks</h1><p>Keep track of what needs doing, one step at a time.</p></div><button class="primary" id="new-task">＋ &nbsp;New task</button></section>
<div class="summary"><div class="metric"><strong id="total-count">0</strong> total</div><div class="metric"><strong id="open-count">0</strong> remaining</div><div class="metric"><strong id="done-count">0</strong> completed</div></div>
<div class="toolbar"><div class="tabs"><button class="tab active" data-filter="all">All tasks</button><button class="tab" data-filter="open">To do</button><button class="tab" data-filter="done">Completed</button></div><label class="search"><input id="search" placeholder="Search tasks…" aria-label="Search tasks"></label></div><section id="task-list" class="task-list" aria-live="polite"></section><div id="empty" class="empty" hidden></div></main></div>
<div class="modal-backdrop" id="modal"><form class="modal" id="task-form"><div class="modal-head"><h2 id="modal-title">New task</h2><button type="button" class="close" id="close-modal" aria-label="Close">×</button></div><input type="hidden" id="task-id"><div class="field"><label for="title">Task name</label><input id="title" name="title" maxlength="255" placeholder="What needs to get done?" required></div><div class="field"><label for="description">Details <span style="font-weight:400;color:#929c94">· optional</span></label><textarea id="description" name="description" placeholder="Add a little more context…"></textarea></div><div class="field"><label for="due-date">Due date <span style="font-weight:400;color:#929c94">· optional</span></label><input type="datetime-local" id="due-date" name="due_date"></div><p class="form-error" id="form-error"></p><div class="modal-actions"><button type="button" class="secondary" id="cancel">Cancel</button><button class="save" type="submit">Save task</button></div></form></div><div class="toast" id="toast" role="status"></div>
<script>
const endpoint='{{ route('tasks.index') }}',token=document.querySelector('meta[name="csrf-token"]').content;
let tasks=[],filter='all';
const list=document.querySelector('#task-list'),empty=document.querySelector('#empty'),modal=document.querySelector('#modal'),form=document.querySelector('#task-form'),error=document.querySelector('#form-error');
function notify(message){const toast=document.querySelector('#toast');toast.textContent=message;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),2300)}
async function request(url,method='GET',body=null){const options={method,headers:{Accept:'application/json','X-CSRF-TOKEN':token}};if(body){options.headers['Content-Type']='application/json';options.body=JSON.stringify(body)}const response=await fetch(url,options);const data=await response.json().catch(()=>({}));if(!response.ok){const message=data.message||Object.values(data.errors||{}).flat()[0]||'Something went wrong. Please try again.';throw new Error(message)}return data}
function render(){const query=document.querySelector('#search').value.trim().toLowerCase();const shown=tasks.filter(task=>(filter==='all'||(filter==='done'?task.completed:!task.completed))&&(`${task.title} ${task.description||''}`.toLowerCase().includes(query)));document.querySelector('#total-count').textContent=tasks.length;document.querySelector('#open-count').textContent=tasks.filter(t=>!t.completed).length;document.querySelector('#done-count').textContent=tasks.filter(t=>t.completed).length;list.innerHTML=shown.map(task=>`<article class="task ${task.completed?'done':''}"><input class="check" type="checkbox" aria-label="Mark ${esc(task.title)} ${task.completed?'not completed':'completed'}" ${task.completed?'checked':''} onchange="toggleTask(${task.id},this.checked)"><div><div class="task-title">${esc(task.title)}</div>${task.description?`<div class="task-desc">${esc(task.description)}</div>`:''}${task.due_label?`<div class="due">◷ &nbsp;${esc(task.due_label)}</div>`:''}</div><div class="actions"><button class="icon-btn" aria-label="Edit ${esc(task.title)}" onclick="editTask(${task.id})">Edit</button><button class="icon-btn delete" aria-label="Delete ${esc(task.title)}" onclick="deleteTask(${task.id})">Delete</button></div></article>`).join('');empty.hidden=shown.length>0;if(!shown.length){empty.innerHTML=tasks.length?'<strong>No matching tasks</strong>Try another search or filter.':'<strong>Your list is clear</strong>Add your first task to get started.'}}
function esc(value){return String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[char]))}
async function load(){try{tasks=await request(endpoint);render()}catch(e){empty.hidden=false;empty.innerHTML=`<strong>Couldn’t load tasks</strong>${esc(e.message)} <button class="secondary" onclick="load()">Try again</button>`}}
function openModal(task=null){form.reset();error.style.display='none';document.querySelector('#task-id').value=task?.id||'';document.querySelector('#modal-title').textContent=task?'Edit task':'New task';document.querySelector('#title').value=task?.title||'';document.querySelector('#description').value=task?.description||'';document.querySelector('#due-date').value=task?.due_date||'';modal.classList.add('open');setTimeout(()=>document.querySelector('#title').focus(),30)}
function closeModal(){modal.classList.remove('open')}
document.querySelector('#new-task').onclick=()=>openModal();document.querySelector('#close-modal').onclick=closeModal;document.querySelector('#cancel').onclick=closeModal;modal.addEventListener('click',e=>{if(e.target===modal)closeModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});document.querySelector('#search').addEventListener('input',render);document.querySelectorAll('.tab').forEach(button=>button.onclick=()=>{filter=button.dataset.filter;document.querySelectorAll('.tab').forEach(tab=>tab.classList.toggle('active',tab===button));render()});
form.onsubmit=async event=>{event.preventDefault();const id=document.querySelector('#task-id').value;const payload={title:document.querySelector('#title').value.trim(),description:document.querySelector('#description').value.trim()||null,due_date:document.querySelector('#due-date').value||null};const save=form.querySelector('.save');save.disabled=true;error.style.display='none';try{await request(id?`${endpoint}/${id}`:endpoint,id?'PATCH':'POST',payload);closeModal();await load();notify(id?'Task updated':'Task created')}catch(e){error.textContent=e.message;error.style.display='block'}finally{save.disabled=false}};
window.editTask=id=>{const task=tasks.find(item=>item.id===id);if(task)openModal(task)};
window.toggleTask=async(id,completed)=>{try{await request(`${endpoint}/${id}`,'PATCH',{completed});await load();notify(completed?'Task completed':'Task reopened')}catch(e){notify(e.message);load()}};
window.deleteTask=async id=>{const task=tasks.find(item=>item.id===id);if(!task||!window.confirm(`Delete “${task.title}”? This cannot be undone.`))return;try{await request(`${endpoint}/${id}`,'DELETE');await load();notify('Task deleted')}catch(e){notify(e.message)}};
load();
</script>
</body>
</html>
